#!/usr/bin/env python3
"""Compute the PFR-internal import closure of the Shannon-information library.

This is the *derivation* of what gets vendored: rather than hand-picking files, we walk
`import` edges from the four entropy-bearing modules and take every PFR-internal module
reachable from them.  That is what keeps PFR's additive-combinatorics machinery
(`ForMathlib/Entropy/Group.lean`, the Ruzsa-distance development, `AddCombi`) out of the
vendored tree: nothing in the entropy closure imports it.

Usage (normally via `vendor-pfr.sh`):

    SRC=<pfr checkout> DST=<repo root> python3 closure.py [--print-only]

`SRC` is a checkout of teorth/pfr at the pinned commit; `DST` is the FAF repository root,
under which the closure is written to `PFR/…` at *upstream module paths* so that future
diffs against upstream stay intelligible.
"""
import os
import re
import shutil
import sys
from collections import deque

SRC = os.environ["SRC"]
DST = os.environ["DST"]
PRINT_ONLY = "--print-only" in sys.argv

# The entropy-bearing modules.  `Basic` alone would reach the rest, but naming all four
# documents the intended surface and makes the closure independent of upstream's internal
# import wiring.
SEEDS = [
    "PFR.ForMathlib.Entropy.Basic",
    "PFR.ForMathlib.Entropy.Measure",
    "PFR.ForMathlib.Entropy.Kernel.Basic",
    "PFR.ForMathlib.Entropy.Kernel.MutualInfo",
]

# PFR at this commit uses the Lean module system, so imports carry `public`/`meta`/`private`.
IMPORT = re.compile(r"\s*(?:public\s+|meta\s+|private\s+)*import\s+([A-Za-z0-9_.]+)")


def path_of(root, mod):
    return os.path.join(root, mod.replace(".", "/") + ".lean")


def imports_of(mod):
    p = path_of(SRC, mod)
    if not os.path.exists(p):
        return None
    with open(p, encoding="utf-8") as fh:
        return [m.group(1) for m in map(IMPORT.match, fh) if m]


seen, deps, external = set(), {}, set()
dq = deque(SEEDS)
while dq:
    mod = dq.popleft()
    if mod in seen:
        continue
    seen.add(mod)
    if not mod.startswith("PFR"):
        external.add(mod)
        continue
    imps = imports_of(mod)
    if imps is None:
        raise SystemExit("missing source for module %s" % mod)
    deps[mod] = [i for i in imps if i.startswith("PFR")]
    dq.extend(i for i in imps if i not in seen)

# Topological order, so the closure can be compiled file-by-file without lake.
order, mark = [], {}


def visit(mod):
    state = mark.get(mod)
    if state == 2:
        return
    if state == 1:
        raise SystemExit("import cycle at " + mod)
    mark[mod] = 1
    for d in deps.get(mod, []):
        visit(d)
    mark[mod] = 2
    order.append(mod)


for mod in sorted(deps):
    visit(mod)

total = sum(sum(1 for _ in open(path_of(SRC, m), encoding="utf-8")) for m in order)

if PRINT_ONLY:
    print("PFR-internal closure: %d modules, %d lines" % (len(order), total))
    for m in order:
        n = sum(1 for _ in open(path_of(SRC, m), encoding="utf-8"))
        print("  %5d  %s" % (n, m))
    print("\nexternal imports pulled in: %d" % len(external))
    for m in sorted(external):
        print("  ", m)
    raise SystemExit(0)

shutil.rmtree(os.path.join(DST, "PFR"), ignore_errors=True)
for mod in order:
    src, dst = path_of(SRC, mod), path_of(DST, mod)
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    shutil.copy(src, dst)

with open(os.path.join(DST, "ShannonInformation/vendor/CLOSURE.txt"), "w") as fh:
    fh.write(
        "# PFR-internal import closure of the Shannon-information library.\n"
        "# Generated by ShannonInformation/vendor/closure.py; topological build order.\n"
        "# %d modules, %d lines.\n" % (len(order), total)
    )
    fh.write("\n".join(order) + "\n")

with open(os.path.join(DST, "ShannonInformation/vendor/EXTERNAL-IMPORTS.txt"), "w") as fh:
    fh.write(
        "# Non-PFR modules the vendored closure imports.  All must be Mathlib: an entry\n"
        "# here from AddCombi or any other PFR dependency would mean the closure has\n"
        "# reached beyond information theory.\n"
    )
    fh.write("\n".join(sorted(external)) + "\n")

print("   %d modules, %d lines vendored to %s/PFR" % (len(order), total, DST))
